bUiListenerMixin(PolymerElement);class SetTimeDialogElement extends SetTimeDialogBase{constructor(){super(...arguments);this.browserProxy_=SetTimeBrowserProxyImpl.getInstance();this.prevValues_={dateInput:"",timeInput:""};this.timeTimeoutId_=null}static get is(){return"set-time-dialog"}static get template(){return getTemplate()}static get properties(){return{timezoneItems_:{type:Array,readOnly:true,value:getTimezoneItems},isTimezoneVisible_:{type:Boolean,readOnly:true,value(){return loadTimeData.getBoolean("showTimezone")}},minDate_:{type:String,readOnly:true,value:getMinDate},maxDate_:{type:String,readOnly:true,value:getMaxDate},selectedTimezone_:{type:String,value(){return loadTimeData.getString("currentTimezoneId")}}}}connectedCallback(){super.connectedCallback();this.addWebUiListener("system-clock-updated",this.updateTime_.bind(this,new Date));this.addWebUiListener("system-timezone-changed",this.setTimezone_.bind(this));this.addWebUiListener("validation-complete",this.saveAndClose_.bind(this));this.browserProxy_.sendPageReady();this.$.dialog.showModal()}ready(){super.ready();this.updateTime_(new Date)}getInputTime_(){const date=this.$.dateInput.valueAsDate;assert(date);date.setMilliseconds(this.$.timeInput.valueAsNumber);date.setSeconds(date.getSeconds()+(new Date).getSeconds());date.setMinutes(date.getMinutes()+date.getTimezoneOffset());return date}getInputTimeSinceEpoch_(){const now=this.getInputTime_();if(this.isTimezoneVisible_){const timezoneDelta=getTimezoneDelta(loadTimeData.getString("currentTimezoneId"),this.selectedTimezone_);now.setMilliseconds(now.getMilliseconds()+timezoneDelta)}return Math.floor(now.getTime()/1e3)}setTimezone_(timezoneId){if(this.isTimezoneVisible_){const timezoneSelect=this.shadowRoot.querySelector("#timezoneSelect");assert(timezoneSelect);assert(timezoneSelect.childElementCount>0);timezoneSelect.value=timezoneId}const now=this.getInputTime_();const timezoneDelta=getTimezoneDelta(timezoneId,this.selectedTimezone_);now.setMilliseconds(now.getMilliseconds()+timezoneDelta);this.selectedTimezone_=timezoneId;this.updateTime_(now)}updateTime_(newTime){if(document.activeElement.id!=="dateInput"&&document.activeElement.id!=="timeInput"){const htmlValues=dateToHtmlValues(newTime);this.prevValues_.dateInput=this.$.dateInput.value=htmlValues.date;this.prevValues_.timeInput=this.$.timeInput.value=htmlValues.time}if(this.timeTimeoutId_){window.clearTimeout(this.timeTimeoutId_)}const secondsRemaining=60-newTime.getSeconds();const nextTime=new Date(newTime.setSeconds(newTime.getSeconds()+secondsRemaining));this.timeTimeoutId_=window.setTimeout(this.updateTime_.bind(this,nextTime),secondsRemaining*1e3)}applyTime_(){this.browserProxy_.setTimeInSeconds(this.getInputTimeSinceEpoch_())}onInputBlur_(e){const inputEl=e.target;assertInstanceof(inputEl,HTMLInputElement);const valueKey=inputEl.type==="date"?"dateInput":"timeInput";if(inputEl.value&&inputEl.validity.valid){this.prevValues_[valueKey]=inputEl.value}else{inputEl.value=this.prevValues_[valueKey]}this.updateTime_(this.getInputTime_())}onTimezoneChange_(e){const selectEl=e.currentTarget;assertInstanceof(selectEl,HTMLSelectElement);this.setTimezone_(selectEl.value)}onDoneClick_(){this.browserProxy_.doneClicked(this.getInputTimeSinceEpoch_())}saveAndClose_(){this.applyTime_();if(this.isTimezoneVisible_){this.browserProxy_.setTimezone(this.selectedTimezone_)}this.browserProxy_.dialogClose()}}customElements.define(SetTimeDialogElement.is,SetTimeDialogElement);